import numpy as np
from scipy.ndimage import label
def transform(grid):
    a=np.array(grid,dtype=int)
    lab,n=label(a==0)
    comps=[(int((lab==i).sum()),i) for i in range(1,n+1)]
    if comps:
        _,i=max(comps); a[lab==i]=8
        remain=[(s,j) for s,j in comps if j!=i]
        if remain:
            _,j=min(remain); a[lab==j]=7
    return a.tolist()
